import forge.ai.*;import forge.game.*;import forge.game.card.*;import forge.game.combat.*;import forge.game.keyword.*;import forge.game.phase.*;import forge.game.player.*;import forge.game.spellability.*;import forge.game.zone.*;import org.testng.Assert;import java.util.*;
public class MarchShieldRegression extends CounterRescuePaymentRegression {
 int groups; void run(String profile,int mode,boolean baseline){Game g=initAndCreateThreePlayerGame();Player ai=g.getPlayers().get(1),enemy=g.getPlayers().get(0);System.setProperty("forge.ai.ggsPilotPlayer",ai.getName());for(Player p:g.getPlayers())fillLibrary(p,20);System.setProperty("dragonmind.strategyProfile",profile);int life=mode==4?30:5+Math.min(mode,2);ai.setLife(life,null);for(int i=0;i<10;i++)addCard("Island",ai);
 Card bayek=addCard("Bayek of Siwa",enemy);bayek.setCounters(CounterEnumType.P1P1,4);if(mode!=3)addCard("Sphere Grid",enemy);addCard("Lightning Greaves",enemy).attachToEntity(bayek,null);Card ezio=addCard("Ezio Auditore da Firenze",enemy);addCard("Brotherhood Regalia",enemy).attachToEntity(ezio,null);
 Card ggs=addCard("Goro-Goro and Satoru",ai),hire=addCard("Grim Hireling",ai),satoru=addCard("Satoru Umezawa",ai);List<Card> shields=List.of(ggs,hire,satoru);for(Card c:List.of(bayek,ezio,ggs,hire,satoru)){c.setSickness(false);c.setTurnInZone(-1);}g.getAction().checkStateEffects(true);
 Assert.assertEquals(bayek.getNetCombatDamage(),7);Assert.assertEquals(bayek.hasKeyword(Keyword.TRAMPLE),mode!=3);Assert.assertTrue(bayek.hasKeyword(Keyword.DOUBLE_STRIKE));Assert.assertTrue(bayek.hasKeyword(Keyword.SHROUD));
 Combat combat=new Combat(enemy);combat.addAttacker(bayek,ai);combat.addAttacker(ezio,ai);combat.setBlocked(bayek,true);combat.setBlocked(ezio,false);for(Card c:shields)combat.addBlocker(bayek,c);g.getPhaseHandler().setCombat(combat);g.getPhaseHandler().devModeSet(PhaseType.COMBAT_DECLARE_BLOCKERS,enemy,false);Assert.assertTrue(CombatUtil.validateAttackers(combat));Assert.assertNull(CombatUtil.validateBlocks(combat,ai));combat.orderBlockersForDamageAssignment();combat.orderAttackersForDamageAssignment();
 Card march=addCardToZone("March of Swirling Mist",ai,ZoneType.Hand);var choice=((PlayerControllerAi)ai.getController()).getAi().chooseSpellAbilityToPlay();Assert.assertNotNull(choice);SpellAbility cast=choice.get(0);Assert.assertEquals(cast.getHostCard(),march);System.out.println("ACTUAL_CHOICE targets="+cast.getTargets()+" X="+cast.getXManaCostPaid());Assert.assertEquals(cast.getTargets().getTargetCards().size(),!baseline&&mode<3?1:4);Assert.assertFalse(cast.canTarget(bayek));for(Card c:cast.getTargets().getTargetCards())Assert.assertTrue(cast.canTarget(c));int paidX=cast.getXManaCostPaid();Assert.assertTrue(ComputerUtilCost.canPayCost(cast,ai,false));Assert.assertTrue(ComputerUtil.handlePlayingSpellAbility(ai,cast,null));drain(g);Assert.assertTrue(ezio.isPhasedOut());Assert.assertEquals(ai.getLandsInPlay().stream().filter(Card::isTapped).count(),(long)paidX+3,"March X+U plus actual ward2 payment");System.out.println("PAID lands="+ai.getLandsInPlay().stream().filter(Card::isTapped).count()+" shields="+shields.stream().map(Card::isPhasedOut).toList());
 combat.assignCombatDamage(true);combat.dealAssignedDamage();System.out.println("FIRST_STRIKE life="+ai.getLife());g.getAction().checkStateEffects(true);drain(g);if(ai.getLife()>0){combat.assignCombatDamage(false);combat.dealAssignedDamage();g.getAction().checkStateEffects(true);drain(g);}System.out.println("SHIELD_RESULT profile="+profile+" mode="+mode+" baseline="+baseline+" life="+ai.getLife());Assert.assertEquals(ai.getLife(),mode==3?life:mode==4?15:baseline?life-7:life-4);groups++;}
 public static void main(String[]args){MarchShieldRegression t=new MarchShieldRegression();t.initializeModel();boolean baseline=Arrays.asList(args).contains("--baseline");for(String profile:List.of("BALANCED","ENGINE","ECONOMY"))for(int mode=0;mode<3;mode++)t.run(profile,mode,baseline);t.run("BALANCED",3,baseline);t.run("BALANCED",4,baseline);System.out.println("Checks passed: "+t.groups);System.exit(0);}
}
